@main
struct ShopApp: App {
    @UIApplicationDelegateAdaptor(AppDelegate.self) var appDelegate
    @Environment(\.scenePhase) private var phase

    var body: some Scene {
        WindowGroup { ProductListView() }
            .onChange(of: phase) { _, newPhase in
                if newPhase == .background { Store.shared.save() }
            }
    }
}

struct ProductListView: View {
    @State private var model = ProductListModel()
    @State private var query = ""

    var body: some View {
        List(model.products) { ProductRow(product: $0) }
            .searchable(text: $query)
            .task(id: query) {                 // cancels the old search automatically
                try? await Task.sleep(for: .milliseconds(300))   // simple debounce
                await model.search(query)
            }
    }
}
